<?php include 'header.php';require_once __DIR__.'/../leave.php';$employeeId=(int)$_SESSION['employeeId'];$year=(int)date('Y');$flash=$_SESSION['leave_flash']??'';unset($_SESSION['leave_flash']);$balances=mysqli_query($conn,'SELECT b.*,t.name,(b.opening_balance+b.credited+b.adjusted-b.used-b.pending) available FROM employee_leave_balances b JOIN leavetypetbl t ON t.id=b.leave_type_id WHERE b.employee_id='.$employeeId.' AND b.balance_year='.$year.' ORDER BY t.name');$types=mysqli_query($conn,'SELECT p.leave_type_id,t.name,p.allow_half_day FROM leave_policies p JOIN leavetypetbl t ON t.id=p.leave_type_id JOIN employeestbl e ON e.company_id=p.company_id WHERE e.id='.$employeeId.' AND p.status=1 ORDER BY t.name');$requests=mysqli_query($conn,'SELECT r.*,t.name type_name FROM leave_requests r JOIN leavetypetbl t ON t.id=r.leave_type_id WHERE r.employee_id='.$employeeId.' ORDER BY r.id DESC');$comp=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COALESCE(SUM(credit_days-debit_days),0) balance FROM comp_off_ledger WHERE employee_id=$employeeId AND status='available' AND (expiry_date IS NULL OR expiry_date>=CURDATE())"));?>
<div id="page-wrapper" class="compact-employee-page leave-center-page"><?php if($flash):?><div class="alert alert-success"><?php echo htmlspecialchars($flash);?></div><?php endif;?><div class="leave-balance-strip"><?php while($b=mysqli_fetch_assoc($balances)):?><div><small><?php echo htmlspecialchars($b['name']);?></small><strong><?php echo number_format($b['available'],1);?></strong><span><?php echo number_format($b['used'],1);?> used · <?php echo number_format($b['pending'],1);?> pending</span></div><?php endwhile;?><div class="comp-off-balance"><small>Comp-Off</small><strong><?php echo number_format($comp['balance'],1);?></strong><span>available credits</span></div></div>
<div class="leave-center-grid"><div class="panel panel-default"><div class="panel-heading">Apply Leave</div><div class="panel-body"><form method="post" action="leaveAction.php" class="leave-apply-form"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="apply"><div class="form-group"><label>Leave Type</label><select class="form-control" name="leave_type_id" required><option value="">Select leave type</option><?php while($t=mysqli_fetch_assoc($types)):?><option value="<?php echo (int)$t['leave_type_id'];?>"><?php echo htmlspecialchars($t['name']);?></option><?php endwhile;?></select></div><div class="form-group"><label>Subject</label><input class="form-control" name="subject" required></div><div class="leave-date-grid"><div class="form-group"><label>Start Date</label><input type="date" class="form-control" name="start_date" min="<?php echo date('Y-m-d');?>" required></div><div class="form-group"><label>End Date</label><input type="date" class="form-control" name="end_date" min="<?php echo date('Y-m-d');?>" required></div></div><label class="leave-half"><input type="checkbox" name="half_day" value="1"> Half-day leave</label><div class="form-group"><label>Description</label><textarea class="form-control" name="description" required></textarea></div><button class="btn btn-primary"><i class="fa fa-paper-plane"></i> Submit Request</button></form></div></div>
<div class="panel panel-default"><div class="panel-heading">My Leave Requests</div><div class="panel-body table-responsive"><table class="table leave-table"><thead><tr><th>Dates</th><th>Type</th><th>Days</th><th>Sandwich</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php if(mysqli_num_rows($requests)===0):?><tr><td colspan="6" class="empty-cell">No leave requests.</td></tr><?php endif;?><?php while($r=mysqli_fetch_assoc($requests)):?><tr><td><strong><?php echo htmlspecialchars($r['start_date']);?></strong><small>to <?php echo htmlspecialchars($r['end_date']);?></small></td><td><?php echo htmlspecialchars($r['type_name']);?></td><td><?php echo number_format($r['payable_days'],1);?></td><td><?php echo number_format($r['sandwich_days'],1);?></td><td><span class="leave-status <?php echo $r['status'];?>"><?php echo ucfirst($r['status']);?></span></td><td><?php echo htmlspecialchars($r['approver_note']);?></td></tr><?php endwhile;?></tbody></table></div></div></div></div></div><?php include 'footer.php';?>